function getInputValues() {
  const genderTextMap = {
    w: "Patientin",
    m: "Patient",
    d: "Patientin/Patient"
  };

  const genderCaseMap = {
    w: {
      nominativ: "die Patientin",
      genitiv: "der Patientin",
      dativ: "der Patientin",
      akkusativ: "die Patientin"
    },
    m: {
      nominativ: "der Patient",
      genitiv: "des Patienten",
      dativ: "dem Patienten",
      akkusativ: "den Patienten"
    },
    d: {
      nominativ: "der Patientin/dem Patient",
      genitiv: "der Patientin/dem Patient",
      dativ: "der Patientin/dem Patient",
      akkusativ: "die Patientin/den Patienten"
    }
  };

  const getValue = (selector, fallback = '') =>
    document.querySelector(selector)?.value.trim() || fallback;
  const getByIndex = (selector, index, fallback = '') =>
    document.querySelectorAll(selector)[index]?.value.trim() || fallback;
  
  function isCardChecked(id) {
    const el = document.getElementById(id);
    return el ? el.checked : false;
  }

  function getCheckedValue(group) {
    const checked = document.querySelector(`input[data-group="${group}"]:checked`);
    if (!checked) return 'nicht angegeben';
    
    if (checked.name.includes('unbekannt')) return 'nicht bekannt';
    if (checked.name.includes('keine')) return 'keine';
    if (checked.name.includes('vorhanden')) return 'folgende:';
    if (checked.name.includes('bekannt')) return 'bekannt';
    if (checked.name.includes('nicht')) return 'nicht berücksichtigt';
    if (checked.name.includes('ja')) return 'berücksichtigt';
    
    return checked.name;
  }

  const selectedGender = document.querySelector('input[name="gender"]:checked')?.value;
  const patientName = document.getElementById("patient-name")?.value.trim() || '';
  
  const genderForText = selectedGender || 'd';

  function getGenderText(caseType = 'nominativ', useName = false) {
    if (useName && patientName !== '') {
      return patientName;
    }
    return genderCaseMap[genderForText][caseType]; 
  }

  return {
    apothekenName: document.getElementById("apothekenname")?.value.trim() || "[Apothekenname]",
    apothekerName: document.getElementById("apo-name")?.value.trim() || "[Name Apotheker:in]",
    apothekeStrasse: document.getElementById("apotheken-strasse")?.value.trim() || "[Straße Hausnummer Apotheke]",
    apothekePLZOrt: document.getElementById("apotheken-ort")?.value.trim() || "[PLZ Ort Apotheke]",

    praxisName: document.getElementById("praxisname")?.value.trim() || "[Praxisname]",
    arztNamePraxis: document.getElementById("arzt-name")?.value.trim() || "[Name Ärztin/Arzt]",
    praxisStrasse: document.getElementById("praxis-strasse")?.value.trim() || "[Straße Hausnummer Praxis]",
    praxisPLZOrt: document.getElementById("praxis-ort")?.value.trim() || "[PLZ Ort Praxis]",

    datumBrief: document.getElementById("datum-brief")?.value.trim() || "[Datum Erstellung]",
    apothekerEmail: document.getElementById("apo-email")?.value.trim() || "[E-Mail Apotheker:in]",
    apothekerTelefon: document.getElementById("apo-telefon")?.value.trim() || "[Telefon Apotheker:in]",
    
    patientName: patientName || "[Vorname Name]",
    patientGeburtsdatum: document.getElementById("patient-geburtsdatum")?.value.trim() || "[Geburtsdatum]",
    gender: selectedGender || '', 
    
    genderText: genderTextMap[genderForText], 
    genderTextNominativ: getGenderText('nominativ', false), 
    genderTextAkkusativ: getGenderText('akkusativ', false), 
    genderTextDativ: getGenderText('dativ', false), 
    genderTextGenitiv: getGenderText('genitiv', false), 
    
    genderTextWithName: getGenderText('nominativ', true),
    genderTextAkkusativWithName: getGenderText('akkusativ', true),

    anredeText: document.getElementById("anrede-text")?.value.trim() || "Sehr geehrte/ Sehr geehrter",
    arztName: getValue('input[placeholder="Name Ärztin/Arzt"]', "[Name Ärztin/Arzt]"),
    grund: getValue('input[placeholder="optional: auf Wunsch von… / auf Grund von…"]', "[optional: auf Wunsch von…/ auf Grund von…]"),
    medikationsbriefInfo: document.querySelector('input[name="medikationsbrief-info"]:checked')?.value || 'nicht angegeben',
    
    symptomeValue: getCheckedValue('symptome'),
    symptomeText: document.getElementById("symptom-textarea")?.value.trim(),
    
    nierenfunktionValue: getCheckedValue('nierenfunktion'),
    nierenfunktionText: document.getElementById("nierenfunktion-textarea")?.value.trim() || '',
    nierenfunktionDatum: document.getElementById("datum-nierenfunktion")?.value.trim() || '',
    nierenfunktionQuelle: document.getElementById("quelle")?.value.trim() || '',
    nierenfunktionBegruendung: document.getElementById("begruendung")?.value.trim() || '',
    
    beruecksichtigung: getCheckedValue('beruecksichtigung'),
    
    keineAuffaelligkeiten: isCardChecked("keine-auffaelligkeiten"),
    mitAuffaelligkeiten: isCardChecked("mit-auffaelligkeiten"),
    datumMedikationsplan: document.getElementById("datum-medikationsplan")?.value.trim() || "[TT.MM.JJJJ]",
    zusatztext: document.getElementById("zusatztext-output")?.textContent.trim() || "",

    logoBase64_pDL: "data:image/png;base64,"
  };
}


